61: function startAudio() {
62:   const AudioContext = window.AudioContext || window.webkitAudioContext;
63:   if (!AudioContext) return;
64:   if (!audio.context) {
65:     audio.context = new AudioContext();
66:     audio.master = audio.context.createGain();
67:     audio.master.gain.value = 0.13;
68:     audio.master.connect(audio.context.destination);
69:     audio.drive = audio.context.createWaveShaper();
70:     const curve = new Float32Array(4096);
71:     for (let i = 0; i < curve.length; i += 1) {
72:       const x = (i * 2) / curve.length - 1;
73:       curve[i] = Math.tanh(x * 5);
74:     }
75:     audio.drive.curve = curve; audio.drive.oversample = '4x'; audio.drive.connect(audio.master);
76:   }
77:   audio.context.resume();
78:   if (audio.musicTimer) return;
79:   const riff = [41.2, 41.2, 49, 41.2, 55, 49, 41.2, 61.7, 41.2, 41.2, 49, 55, 41.2, 49, 36.7, 41.2];
80:   audio.musicTimer = window.setInterval(() => {
81:     if (!world.running || !audio.context) return;
82:     const ctx = audio.context;
83:     const now = ctx.currentTime;
84:     const step = audio.musicStep++ % riff.length;
85:     if ([0, 4, 8, 12].includes(step)) {
86:       const kick = ctx.createOscillator(); const volume = ctx.createGain();
87:       kick.type = 'sine'; kick.frequency.setValueAtTime(115, now); kick.frequency.exponentialRampToValueAtTime(38, now + 0.12);
88:       volume.gain.setValueAtTime(0.28, now); volume.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
89:       kick.connect(volume); volume.connect(audio.master); kick.start(now); kick.stop(now + 0.15);
90:     } else if ([2, 6, 10, 14].includes(step)) {
91:       const snare = ctx.createOscillator(); const volume = ctx.createGain();
92:       snare.type = 'triangle'; snare.frequency.value = 175;
93:       volume.gain.setValueAtTime(0.12, now); volume.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
94:       snare.connect(volume); volume.connect(audio.master); snare.start(now); snare.stop(now + 0.09);
95:     }
96:     if (step % 2 === 0) {
97:       const root = riff[step];
98:       [root, root * 1.5].forEach((frequency) => {
99:         const osc = ctx.createOscillator(); const gain = ctx.createGain(); const filter = ctx.createBiquadFilter();
100:         osc.type = 'sawtooth'; osc.frequency.value = frequency;
101:         filter.type = 'lowpass'; filter.frequency.value = 420;
102:         gain.gain.setValueAtTime(0.095, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
103:         osc.connect(filter); filter.connect(gain); gain.connect(audio.drive); osc.start(now); osc.stop(now + 0.21);
104:       });
105:     }
106:   }, 220);
107: }
