352: function detonateBomb(bomb) {
353:   scene.remove(bomb.model);
354:   const radius = 105;
355:   for (let i = world.zombies.length - 1; i >= 0; i -= 1) {
356:     const zombie = world.zombies[i];
357:     const distance = dist(bomb.x, bomb.y, zombie.x, zombie.y);
358:     if (distance < radius) {
359:       zombie.hp -= 72 * (1 - distance / (radius * 1.5));
360:       zombie.hitFlash = 0.12;
361:       if (zombie.hp <= 0) {
362:         world.score += 15; scene.remove(zombie.model); world.zombies.splice(i, 1);
363:         if (Math.random() < 0.22) addPickup(zombie.x, zombie.y, 'ammo');
364:       }
365:     }
366:   }
367:   for (const car of world.cars) if (dist(bomb.x, bomb.y, car.x, car.y) < radius + 24) car.hp -= 90;
368:   createExplosion(bomb.x, bomb.y, radius, 0xff5d73);
369:   hud.status.textContent = 'Bomb detonated!';
370: }
371: function updateBombs(dt) {
