373:     const bomb = world.bombs[i];
374:     bomb.age += dt; bomb.x += bomb.vx * dt; bomb.y += bomb.vy * dt;
375:     const arc = Math.sin(Math.min(1, bomb.age / bomb.fuse) * Math.PI) * 1.25;
376:     bomb.model.position.copy(toScene(bomb.x, bomb.y, 0.25 + arc));
377:     bomb.model.rotation.x += dt * 8; bomb.model.rotation.z += dt * 6;
378:     if (bomb.age >= bomb.fuse) {
379:       detonateBomb(bomb); world.bombs.splice(i, 1);
380:     }
381:   }
